        for (int i = 0; i < month - 1; i++) ans += md[i];
        ans += day;
        System.out.println(ans);
    }

    static boolean isLeap(int y) {
        return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    }
}

