public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        line = line.trim();
        int sep = line.indexOf(';');
        int m = Integer.parseInt(line.substring(0, sep).trim());
        int n = Integer.parseInt(line.substring(sep + 1).trim());
        StringBuilder sb = new StringBuilder("[");
        boolean first = true;
        for (int x = m; x <= n; x++) {
            int a = x / 100;
            int b = (x / 10) % 10;
            int c = x % 10;
            if (a * a * a + b * b * b + c * c * c == x) {
                if (!first) sb.append(',');
                sb.append(x);
                first = false;
            }
        }
        sb.append(']');
        System.out.println(sb.toString());
    }
}

