public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        line = line.trim();
        int sep = line.indexOf(';');
        String[] parts = line.substring(0, sep).trim().split("-");
        int year = Integer.parseInt(parts[0].trim());
        int month = Integer.parseInt(parts[1].trim());
        int day = Integer.parseInt(parts[2].trim());
        long k = Long.parseLong(line.substring(sep + 1).trim());
        for (long i = 0; i < k; i++) {
            day++;
            if (day > daysInMonth(year, month)) {
                day = 1;
                month++;
                if (month > 12) {
                    month = 1;
                    year++;
                }
            }
        }
        System.out.println(String.format("%04d-%02d-%02d", year, month, day));
    }

    static int daysInMonth(int y, int m) {
        int[] md = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (m == 2 && isLeap(y)) return 29;
        return md[m - 1];
    }

    static boolean isLeap(int y) {
        return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    }
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        line = line.trim();
        int sep = line.indexOf(';');
        String[] p1 = line.substring(0, sep).trim().split("-");
        String[] p2 = line.substring(sep + 1).trim().split("-");
        long d1 = toDays(Integer.parseInt(p1[0].trim()), Integer.parseInt(p1[1].trim()), Integer.parseInt(p1[2].trim()));
        long d2 = toDays(Integer.parseInt(p2[0].trim()), Integer.parseInt(p2[1].trim()), Integer.parseInt(p2[2].trim()));
        System.out.println(Math.abs(d1 - d2));
    }

    static long toDays(int year, int month, int day) {
        long days = 0;
        for (int y = 1900; y < year; y++) days += isLeap(y) ? 366 : 365;
        int[] md = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (isLeap(year)) md[1] = 29;
        for (int i = 0; i < month - 1; i++) days += md[i];
        return days + day - 1;
    }

    static boolean isLeap(int y) {
        return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    }
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        line = line.trim();
        int sep = line.indexOf(';');
        long n = Long.parseLong(line.substring(0, sep).trim());
        int b = Integer.parseInt(line.substring(sep + 1).trim());
        if (n == 0) {
            System.out.println(0);
            return;
        }
        StringBuilder sb = new StringBuilder();
        while (n > 0) {
            int r = (int) (n % b);
            sb.append(r < 10 ? (char) ('0' + r) : (char) ('A' + r - 10));
            n /= b;
        }
        System.out.println(sb.reverse().toString());
    }
}

