        line = line.trim();
        int sep = line.indexOf(';');
        int a = Integer.parseInt(line.substring(0, sep).trim());
        int b = Integer.parseInt(line.substring(sep + 1).trim());
        boolean[] composite = new boolean[b + 1];
        int count = 0;
        for (int i = 2; i <= b; i++) {
            if (!composite[i]) {
                if (i >= a) count++;
                for (long j = (long) i * i; j <= b; j += i) composite[(int) j] = true;
            }
        }
        System.out.println(count);
    }
}

