        String line = br.readLine();
        if (line == null) return;
        long n = Long.parseLong(line.trim());
        System.out.println(sumOfMultiples(n, 3) + sumOfMultiples(n, 5) - sumOfMultiples(n, 15));
    }

    static long sumOfMultiples(long n, long d) {
        long m = n / d;
        return d * (m * (m + 1) / 2);
    }
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        line = line.trim();
        int sep = line.indexOf(';');
        long n = Long.parseLong(line.substring(0, sep).trim());
        int d = Integer.parseInt(line.substring(sep + 1).trim());
        long total = 0;
        long p = 1;
        while (p <= n) {
            long high = n / (p * 10);
            long cur = (n / p) % 10;
            long low = n % p;
            if (d == 0) {
                if (high > 0) {
                    total += (high - 1) * p;
                    if (cur > 0) total += p;
                    else total += low + 1;
                }
            } else {
                total += high * p;
                if (cur > d) total += p;
                else if (cur == d) total += low + 1;
            }
            if (p > n / 10) break;
            p *= 10;
        }
        System.out.println(total);
    }
}
